'use strict';

function defaultFactory(origin) {
  return 'pool(' + origin + ')';
}

// undici's Agent constructor shape: named options with defaults, and a rest
// element collecting every other option for the per-origin dispatchers.
class Agent {
  constructor({ factory = defaultFactory, maxOrigins = Infinity, ...options } = {}) {
    this.factory = factory;
    this.maxOrigins = maxOrigins;
    this.options = options;
  }

  describe(origin) {
    return this.factory(origin) + ' max=' + this.maxOrigins + ' ' + JSON.stringify(this.options);
  }
}

module.exports = { Agent };
